import {isSampleRecord} from './model.js';
import {DISCOVERY_GROUPS,discoveryGroup,createDiscoveryClient,placePrefill} from './discovery.js';
import {createPlacesMap} from './places-map.js';
import {createVisitMap} from './visit-map.js';
import {hasLocation} from './atlas.js';
import {latestVisited,placeView} from './visits.js';
import {proximityKm} from './nearby-memories.js';
import {samePlaceSource,placeSourceURL} from './place-source.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const distance=km=>km<1?`${Math.round(km*1000)} m`:`${km.toFixed(1)} km`;
export function createPlacesUI({document,events=globalThis.window,network=globalThis.navigator,L,offlineMaps,getRecords,locate,icon,onPreview,onSave,onSaved,onStatus=()=>{},client=createDiscoveryClient(),Observer=globalThis.IntersectionObserver}){
 const $=id=>document.getElementById(id);let active=false,mapVisible=!Observer,map=null,center=null,areaLabel='',groupId='food',filterId='',items=[],limited=false,loadedKey='',pendingKey='',query='',limit=30,busy=false,request=0,locationRequest=0,selected=null,previewMap=null,previewAlive=false,mapDirty=true,paused=false;
 const available=()=>getRecords().filter(r=>!isSampleRecord(r)&&hasLocation(placeView(r))).sort((a,b)=>latestVisited(b).localeCompare(latestVisited(a)));
 const key=()=>center?`${center.lat.toFixed(3)},${center.lng.toFixed(3)}:${groupId}:${filterId}:${$('places-radius').value}`:'';
 const showing=()=>items.filter(p=>!query||[p.title,p.address,p.kind,p.cuisine].some(v=>v?.toLocaleLowerCase().includes(query)));
 function refreshOrigins(){const chosen=$('places-origin').value;$('places-origin').innerHTML='<option value="">Choose a saved place…</option>'+available().map(r=>`<option value="${esc(r.id)}">${esc(r.title)}</option>`).join('');$('places-origin').value=chosen;}
 function syncVisibility(uncovered=true,pausedValue=paused){paused=pausedValue;if(paused||document.hidden)locationRequest++;if(active&&busy&&(paused||document.hidden)){request++;client.cancel();busy=false;$('places-status').textContent='Search paused. Tap Retry when you return.';render();}const visible=active&&uncovered&&!document.hidden&&!paused;map?.setVisible(visible&&mapVisible);if(visible&&mapVisible&&mapDirty){map?.update(showing());mapDirty=false;}previewMap?.setVisible(previewAlive&&!paused&&!document.hidden&&$('place-preview').open&&![...document.querySelectorAll('dialog[open]')].some(d=>d.id!=='place-preview'));}
 function mapReady(){if(map)return;map=createPlacesMap({container:$('places-map'),L,offlineMaps,pinHTML:icon('footprint'),document,events,network,onPick:id=>open(id),onMove:p=>{const moved=!center||proximityKm(center,{lat:p.lat,lng:p.lng})>=.1;if(moved)locationRequest++;$('places-search-area').hidden=!moved;},onStatus:({state,message})=>{$('places-map-status').textContent=message;$('places-map-retry').hidden=state!=='error';}});map.setVisible(active&&mapVisible);if(center)map.center(center);}
 function categories(){const group=discoveryGroup(groupId);document.querySelector('.places-type-picker').hidden=!group.filters.length;$('places-categories').innerHTML=DISCOVERY_GROUPS.map(g=>`<button type="button" data-discovery-group="${g.id}" class="${g.id===groupId?'active':''}" aria-pressed="${g.id===groupId}">${icon(g.icon)}<span>${esc(g.label)}</span></button>`).join('');$('places-types').innerHTML=(group.filters.length?[{id:'',label:`All ${group.label}`,icon:group.icon},...group.filters]:[]).map(f=>`<button type="button" data-discovery-filter="${f.id}" class="${f.id===filterId?'active':''}" aria-pressed="${f.id===filterId}">${icon(f.icon)}<span>${esc(f.label)}</span></button>`).join('');}
 function render(){
  const rows=showing(),saved=getRecords();$('places-area').textContent=center?`${areaLabel||'Map area'} · ${Number($('places-radius').value)/1000} km radius`:'Choose an area to explore.';
  $('places-results-count').textContent=busy?'Looking for mapped places…':`${rows.length} ${rows.length===1?'place':'places'}${query?' matching your filter':''}${limited?' · this busy area may contain more':''}`;
  $('places-results').innerHTML=rows.slice(0,limit).map(p=>{const exists=saved.some(r=>samePlaceSource(r.placeSource,p.placeSource));return `<button type="button" class="discovery-place" data-discovery-place="${p.id}"><span class="discovery-face">${icon('footprint')}</span><span><strong>${esc(p.title)}</strong><small>${esc(p.kind)} · ${distance(p.km)} from search center${exists?' · Saved':''}</small>${p.address?`<small>${esc(p.address)}</small>`:''}</span>${icon('arrowRight')}</button>`;}).join('');
  $('places-more').hidden=limit>=rows.length;$('places-more').disabled=busy;$('places-empty').hidden=busy||rows.length>0;$('places-empty').textContent=!center?'Use your location, choose a saved place, or move the map and tap Search this area.':query?'No places match this text. Try another filter.':'No matching places are mapped in this area yet. Try another type, a larger radius or a different area.';
  $('places-retry').hidden=!center||busy;$('places-cancel').hidden=!busy;$('places-results').setAttribute('aria-busy',String(busy));mapDirty=true;syncVisibility(!document.querySelector('dialog[open]'));
 }
 async function search(){
  if(!active||!center||paused||document.hidden)return;const token=++request;locationRequest++;pendingKey=key();busy=true;items=[];limit=30;loadedKey='';$('places-status').textContent='Finding places in this area…';render();
  try{const result=await client.search({center:{...center},groupId,filterId,radius:Number($('places-radius').value)});if(token!==request||!active)return;items=result.items;limited=result.limited;loadedKey=pendingKey;$('places-status').textContent=result.cached?'Recently loaded results. Listings may have changed.':limited?'This area has many places. Narrow the type or radius to explore more.':'Places from OpenStreetMap. Details and coverage vary by area.';
  }catch(error){if(token!==request)return;if(error.message!=='CANCELLED')$('places-status').textContent=error.message;}finally{if(token===request){busy=false;render();}}
 }
 function setArea(point,label,zoom=14,searchNow=false){center={lat:point.lat,lng:point.lng};areaLabel=label;mapReady();map.center(center,zoom);$('places-search-area').hidden=searchNow;if(searchNow)void search();else{$('places-status').textContent='Tap Search this area to load nearby listings.';render();}}
 function more(){if(busy)return;const rows=showing();if(limit<rows.length){limit+=30;render();}}
 function closePreview(){previewAlive=false;previewMap?.destroy();previewMap=null;}
 function open(id){const place=items.find(p=>p.id===id);if(!place)return false;closePreview();selected=place;previewAlive=true;map?.select(id);onPreview();renderPreview();return true;}
 function renderPreview(){
  if(!selected||!previewAlive)return;const p=selected,saved=getRecords().find(r=>samePlaceSource(r.placeSource,p.placeSource));
  $('place-preview-content').innerHTML=`<button type="button" class="icon-button detail-top-close" data-close="place-preview" aria-label="Close place">${icon('close')}</button><div class="discovery-hero">${icon('footprint')}<span>ANOTHER PLACE TO REMEMBER</span></div><div class="detail-content"><span class="eyebrow">${esc(p.category)} · ${esc(p.kind)}</span><h2>${esc(p.title)}</h2><p class="address-line">${icon('location')}${esc(p.address||'Address not listed')}</p><p class="field-help">${distance(p.km)} from search center${p.approximate?' · Position is the mapped area’s center':''}</p>${p.description?`<p class="story">${esc(p.description)}</p>`:''}${p.cuisine?`<p><b>Cuisine</b> · ${esc(p.cuisine)}</p>`:''}${p.hours?`<p><b>Mapped hours</b> · ${esc(p.hours)}</p>`:''}<div class="detail-extra">${p.phone?`<a href="tel:${esc(p.phone.replace(/[^+\d*#,;]/g,''))}">${esc(p.phone)}</a>`:''}${p.url?`<a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Visit website ${icon('external')}</a>`:''}</div><p class="field-help">${p.lat.toFixed(6)}°, ${p.lng.toFixed(6)}°</p><div class="visit-map-preview"><div id="discovery-preview-map" class="visit-map" aria-label="Location of ${esc(p.title)}"></div></div><p id="discovery-preview-status" class="field-help" role="status"></p><div class="detail-actions"><button type="button" class="primary" id="keep-discovered-place">${icon(saved?'stack':'plus')}${saved?'Open saved footprint':'Save as footprint'}</button>${saved?'<button type="button" class="secondary" id="visit-discovered-place">Log return visit</button>':''}<a class="secondary" href="https://www.google.com/maps/dir/?api=1&destination=${p.lat},${p.lng}" target="_blank" rel="noopener noreferrer">${icon('navigation')}Directions</a></div><p class="field-help discovery-credit">Place details © <a href="${placeSourceURL(p.placeSource)}" target="_blank" rel="noopener noreferrer">OpenStreetMap contributors</a>. Check details before visiting. Saving opens a draft for your visit date, photos and story.</p></div>`;
  previewMap=createVisitMap({container:$('discovery-preview-map'),record:{...p,photos:[],coverIndex:0},L,offlineMaps,document,pinHTML:icon('footprint'),onStatus:({state,message})=>{if(previewAlive)$('discovery-preview-status').textContent=state==='ready'?'':message;}});
  syncVisibility(!document.querySelector('dialog[open]'));
  $('keep-discovered-place').onclick=()=>saved?onSaved(saved.id):onSave(placePrefill(p));if(saved)$('visit-discovered-place').onclick=()=>onSave(null,saved.id);
 }
 function wire(){
  categories();refreshOrigins();$('places-categories').onclick=e=>{const b=e.target.closest('[data-discovery-group]');if(!b||b.dataset.discoveryGroup===groupId)return;groupId=b.dataset.discoveryGroup;filterId='';query='';$('places-filter').value='';categories();void search();};
  $('places-types').onclick=e=>{const b=e.target.closest('[data-discovery-filter]');if(!b||b.dataset.discoveryFilter===filterId)return;filterId=b.dataset.discoveryFilter;categories();void search();};
  $('places-results').onclick=e=>{const b=e.target.closest('[data-discovery-place]');if(b)open(b.dataset.discoveryPlace);};$('places-more').onclick=more;
  $('places-filter').oninput=e=>{query=e.target.value.trim().toLocaleLowerCase();limit=30;render();};$('places-radius').onchange=()=>void search();$('places-retry').onclick=()=>void search();$('places-map-retry').onclick=()=>map?.retry();
  $('places-cancel').onclick=()=>{request++;client.cancel();busy=false;$('places-status').textContent='Search cancelled.';render();};
  $('places-origin').onchange=e=>{locationRequest++;const r=available().find(r=>r.id===e.target.value);if(r)setArea(placeView(r),r.title);};
  $('places-locate').onclick=async()=>{const token=++locationRequest;$('places-locate').disabled=true;$('places-status').textContent='Finding your location…';try{const p=await locate();if(token!==locationRequest||!active)return;setArea({lat:p.coords.latitude,lng:p.coords.longitude},'Near me · accuracy '+distance(p.coords.accuracy/1000),14,true);}catch(error){if(token===locationRequest)$('places-status').textContent=error.message;}finally{$('places-locate').disabled=false;}};
  $('places-search-area').onclick=()=>{locationRequest++;const p=map?.getCenter()??center;if(p)setArea(p,'Map area',14,true);};
  const mapObserver=Observer?new Observer(entries=>{mapVisible=entries.some(e=>e.isIntersecting);syncVisibility(!document.querySelector('dialog[open]'));},{threshold:0}):null;mapObserver?.observe($('places-map'));
  const moreObserver=Observer?new Observer(entries=>{if(active&&!document.querySelector('dialog[open]')&&entries.some(e=>e.isIntersecting))more();},{rootMargin:'250px'}):null;moreObserver?.observe($('places-more'));
 }
 return {wire,setActive(value){active=value;locationRequest++;refreshOrigins();if(value){mapReady();if(!center){const first=available()[0];if(first){$('places-origin').value=first.id;setArea(placeView(first),first.title);}else{render();$('places-search-area').hidden=false;}}else{render();if(!loadedKey||loadedKey!==key())$('places-search-area').hidden=false;}}else{request++;client.cancel();busy=false;}syncVisibility(!document.querySelector('dialog[open]'));},syncVisibility,refresh(){refreshOrigins();if(active)render();if(previewAlive&&selected){const current=selected.id;closePreview();selected=items.find(p=>p.id===current)??selected;previewAlive=true;renderPreview();}},resumePreview(){if(selected){previewAlive=true;renderPreview();}},closePreview,get selected(){return selected;}};
}
